# team_offirst DR lesion segmenter v6 - SE fix (negative_patches_per_image 2, SE loss weight 3x) on top of v5 camera-robust. 1440 px retina-circle preprocessing, Dice+BCE, patience 12,
# selection on mean AUPR(MA,HE,EX). Lesion supervision: IDRiD SEGMENTATION subset only.
# Healthy negatives: 50 RFMiD TRAINING-split normals (Disease_Risk=0); 10 more as FP monitor.
# DATA RULE: IDRiD grading set and RFMiD held-out val/test sets are NOT mounted and NOT used.
FOV_DIAMETER = 1440
import base64, os, subprocess, sys, pathlib
FILES = {'README.md': '', 'common.py': '', 'config.yaml': '', 'config_v5.yaml': '', 'config_v6.yaml': '', 'fov_mask.py': '', 'inference.py': '', 'model.py': '', 'train.py': ''}
work = pathlib.Path("/kaggle/working/lesion_detector"); work.mkdir(parents=True, exist_ok=True)
for n, b in FILES.items():
    (work / n).write_bytes(base64.b64decode(b))
print("Wrote code:", sorted(os.listdir(work)), flush=True)

subprocess.run("nvidia-smi", shell=True)
print("=== /kaggle/input layout (depth<=4) ===", flush=True)
inp = pathlib.Path("/kaggle/input")
for p in sorted(inp.rglob("*")):
    rel = p.relative_to(inp)
    if len(rel.parts) <= 4 and (p.is_dir() or len(rel.parts) <= 2):
        print(("  " * (len(rel.parts) - 1)) + rel.parts[-1] + ("/" if p.is_dir() else ""))

# Data-usage guard: refuse to run if the IDRiD grading set or RFMiD eval/test images are mounted.
if any(inp.rglob("IDRiD_001test.jpg")) or any(inp.rglob("B. Disease Grading")):
    raise SystemExit("IDRiD grading set is mounted - not allowed for v6")
if any(inp.rglob("RFMiD_Testing_Labels.csv")) or any(inp.rglob("RFMiD_Validation_Labels.csv")):
    raise SystemExit("RFMiD val/test set is mounted - not allowed for v6")

cands = sorted(inp.rglob("1. Original Images"))
if not cands:
    raise SystemExit("Could not find IDRiD '1. Original Images' under /kaggle/input")
seg_root = cands[0].parent
n_tr = len(list((seg_root / "1. Original Images" / "a. Training Set").glob("*.jpg")))
n_te = len(list((seg_root / "1. Original Images" / "b. Testing Set").glob("*.jpg")))
print(f"idrid_root -> {seg_root}  (train jpgs={n_tr}, test jpgs={n_te})", flush=True)

def need(mod):
    try: __import__(mod); return False
    except Exception: return True
pkgs = [p for p, m in [("segmentation-models-pytorch", "segmentation_models_pytorch"), ("timm", "timm"),
                       ("albumentations", "albumentations"), ("scikit-learn", "sklearn")] if need(m)]
if pkgs:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q"] + pkgs, check=True)
subprocess.run([sys.executable, "-c", "import torch, timm, segmentation_models_pytorch as smp, albumentations as A; "
                "print('torch', torch.__version__, 'cuda', torch.cuda.is_available(), 'timm', timm.__version__, 'smp', smp.__version__, 'albu', A.__version__)"])

lab = sorted(inp.rglob("RFMiD_Training_Labels.csv"))
if not lab:
    raise SystemExit("Could not find RFMiD_Training_Labels.csv under /kaggle/input")
neg_root = None
for p in sorted(lab[0].parent.rglob("1.png")):
    neg_root = p.parent; break
if neg_root is None:
    raise SystemExit("Could not find RFMiD training PNGs")
print(f"negatives_root -> {neg_root}  ({len(list(neg_root.glob('*.png')))} pngs)", flush=True)

env = dict(os.environ, TQDM_MININTERVAL="60", PYTHONUNBUFFERED="1")
cmd = [sys.executable, "train.py", "--config", "config_v6.yaml", "--set",
       f"data.idrid_root={seg_root}", f"data.negatives_root={neg_root}", f"data.fov_diameter={FOV_DIAMETER}",
       "training.batch_size=2", "training.grad_accum_steps=4", "training.epochs=40", "training.loss=dice_bce",
       "output.checkpoint_dir=/kaggle/working/ckpt"]
print("Running:", " ".join(cmd), flush=True)
r = subprocess.run(cmd, cwd=work, env=env)
print("train.py exit code", r.returncode, flush=True)
print("Outputs:", os.listdir("/kaggle/working/ckpt") if os.path.isdir("/kaggle/working/ckpt") else "none")
sys.exit(r.returncode)
